import * as THREE from '../../../vendor/three.module.js';
import {buildSakuraShotenInterior} from './sakura-rebuild-shell.js';
import {retainSakuraStock} from './sakura-rebuild-stock.js';
import {sakuraRebuildRequested,sakuraRebuildLayout,SAKURA_REBUILD_OFFSET} from './sakura-rebuild-layout.js';
import {buildSakuraCounterDetail,buildSakuraHotFood} from './sakura-counter-detail.js';
import {buildMagazineRack} from './sakura-magazine-rack.js';
import {buildShelfEdges} from './sakura-shelf-edge.js';
import {buildSakuraShelfStickers} from './sakura-shelf-stickers.js';
import {buildSakuraBaskets} from './sakura-baskets.js';
import {SHOP_STOCK} from '../../commerce/shop-stock.js';
import {buildSlidingLeaves,doorState,stepDoor,SLIDING_DOOR} from '../sliding-door.js';
import {townCalendarAt} from '../../town-clock.js';
import {PALETTE,fluorescent} from '../../render/dusk.js';

// Noto Sans JP sign subset, SIL OFL 1.1: docs/qa/sakura-retained-stock/OFL-NotoSansJP.txt.
if(sakuraRebuildRequested()&&typeof FontFace!=='undefined'){try{const font=new FontFace('SakuraJP','url(data:font/woff;base64,)');await font.load();document.fonts.add(font);}catch{}}

// Production API candidate, deliberately opt-in while prop/actor/save acceptance is in progress.
export function buildSakuraRebuild({room,reg,action,exit}){
 const omit=(g,x,z,w,d,h,mat,y)=>(g==='ExteriorWalls'&&x===6000&&w===1900)||g==='Fixtures'&&((x===0&&z===0&&w===5800)||(x===5500&&z===800)||(x>=11300&&x<12100&&z<4800&&y>=780)||(x>=13280&&x<=13300&&z>=1800&&z<=3500&&y>=780));
 const shell=buildSakuraShotenInterior(THREE,{placeholderStock:false,doors:false,levelOffice:true,omit});shell.name='Sakura single-storey candidate';shell.userData.sharedAsset=true;shell.position.set(...SAKURA_REBUILD_OFFSET);room.add(shell);
 const g=shell.userData.groups;g.Ceiling.visible=true;g.ExteriorWalls.visible=true;g.Roof.visible=false;
 const stock=retainSakuraStock(shell,{offset:SAKURA_REBUILD_OFFSET,printedExamples:false}),layout=sakuraRebuildLayout(shell.userData.solids);
 const anchor=(pos,label,fn)=>{const o=new THREE.Object3D();o.position.set(...pos);room.add(o);reg(o,label,fn,true);return o;};
 buildShelfEdges(room,{shelves:stock.productShelves,talkers:false});
 const advertising=buildSakuraShelfStickers(room,{shelves:stock.productShelves});
 const equipment=buildSakuraCounterDetail(room,{placements:{till:[.05,0,-.16],microwaves:[[.23,.058,-.24],[.23,.058,-1.44]],supplies:[.23,.058,-.715],copy:[1.85,0,.01],rice:[-.45,-.35,2.4],sandwich:[-.45,-.35,-.43],dairy:[-.45,-.35,-4.1]}});
 const hot={x:4.925,z:-2.065,w:.45,d:.45,h:.4,top:.78};buildSakuraHotFood(room,hot);
 const magazine=buildMagazineRack(room);magazine.group.position.set(-5.85,0,3.60);magazine.group.rotation.y=Math.PI;
 const basket=buildSakuraBaskets(room);basket.position.set(-1.25-(-1.84),0,2.86-3.48);
 // Existing SKU keys, stock-picking anchors and the standard display return contract.
 for(const r of stock.records){const pos=stock.unitPositions.get(r.id+':0');const o=anchor(pos,'Examine '+r.id,()=>{const spec=SHOP_STOCK.find(p=>p.id===r.id);action('store-item',spec.name,spec);});o.userData.storeItem=r.id;}
 anchor(layout.exit,'Exit to street',exit);anchor([4.35,1.0,1.01],'Ring service bell',()=>action('resident','Thuan'));
 anchor([-5.85,1,2.75],'Read the magazines',()=>action('magazine-rack'));
 anchor([4.925,1.1,-2.065],'Ask for hot snacks',()=>action('sakura-hot-snacks'));
 anchor([3.95,1.1,2.7],'Use the copy machine',()=>action('inspect','Copy machine · fax','Copy ¥10 · Fax ¥50. Please ask Thuan.'));
 const fill=new THREE.HemisphereLight(PALETTE.sakuraTube,0xd8d2c4,1.7);room.add(fill);
 const doors=[],frame=new THREE.MeshStandardMaterial({color:0x798d89,metalness:.45,roughness:.36}),glass=new THREE.MeshStandardMaterial({color:0xb4d9d4,transparent:true,opacity:.075,roughness:.15,depthWrite:false,side:THREE.DoubleSide});
 const add=(parent,w,h,d,x,y,z,mat)=>{const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);parent.add(m);};
 for(let i=0;i<8;i++){
  const door=new THREE.Group();door.name='Sakura candidate cooler door '+(i+1);door.position.set(5.4+i*.6-6.95,0,3.91-8.22);room.add(door);
  add(door,.59,2.0,.015,.295,1.21,0,glass);for(const x of [.008,.582])add(door,.016,2.36,.03,x,1.18,0,frame);for(const y of [.105,2.285])add(door,.59,.15,.03,.295,y,0,frame);add(door,.018,.42,.035,.55,1.2,.035,frame);
  const d={door,amount:0,timer:0};doors.push(d);anchor([door.position.x+.30,1.3,door.position.z+.1],'Open chilled drinks',()=>{d.timer=4;});
 }
 const refrigerator={doors,open(i){if(doors[i])doors[i].timer=3;},hold(i,v){const d=doors[i];if(!d)return false;d.amount=THREE.MathUtils.clamp(v,0,1);d.timer=d.amount?1e9:0;d.door.rotation.y=-Math.PI*.48*d.amount;return true;},update(dt){for(const d of doors){d.timer=Math.max(0,d.timer-dt);d.amount=THREE.MathUtils.damp(d.amount,d.timer?1:0,5,dt);d.door.rotation.y=-Math.PI*.48*d.amount;}}};
 const frontGroup=new THREE.Group();frontGroup.name='Sakura front door';frontGroup.position.set(0,0,3.82);room.add(frontGroup);
 const leaves=buildSlidingLeaves({parent:frontGroup,width:1.9,height:2.2,glazing:glass,travel:.85,offset:.025,name:'Sakura front door leaf'}),motion=doorState();let held=false;
 const frontDoor={get amount(){return motion.amount;},set(value){held=value!=null;if(held){motion.amount=THREE.MathUtils.clamp(Number(value)||0,0,1);motion.speed=0;leaves.place(motion.amount);}},update(dt,points=[]){if(held)return;stepDoor(motion,dt,points.some(p=>Math.hypot(p[0],p[1]-3.3)<SLIDING_DOOR.reach));leaves.place(motion.amount);}};
 const drinkIds=['tea','coffee','water','orange','cola','soda','beer'];
 function updateLighting(minutes){if(!Number.isFinite(minutes))return;fill.intensity=1.7*fluorescent(minutes);const date=townCalendarAt(minutes).date;magazine.refresh(date);advertising.setMonth(date.getMonth()+1);}
 const nothing=()=>{};
 return {layout,shell,stock,frontDoor,productShelves:stock.productShelves,unitPositions:stock.unitPositions,unitApproaches:stock.unitApproaches,updateStock:stock.updateStock,refrigerator,accessShelf:id=>refrigerator.open(drinkIds.indexOf(id)),cashDrawer:equipment.getObjectByName('Sakura cash drawer'),updateLighting,smallOffice:{setHours:nothing,setWeather:nothing},decorations:{refresh:nothing,tick:nothing},advertising,ready:async()=>true,loadBackRooms:nothing,tick:(time,minutes)=>updateLighting(minutes),dispose:nothing};
}
